		if opts.SpecialDoerName != "" {
			commentMetaData = &CommentMetaData{
				SpecialDoerName: opts.SpecialDoerName,
			}
		}

		comment := &Comment{
			Type:             opts.Type,
			PosterID:         opts.Doer.ID,
